using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.IO;
using System.Linq;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (EditorApplication.isPlaying)
                throw new Exception("Edit required");
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!s || !s.gameObject.scene.path.EndsWith("r103.unity"))
                throw new Exception("r103 required");
            s.data = new InvestigationSave();
            s.diagnostics = false;
            EditorSceneManager.MarkSceneDirty(s.gameObject.scene);
            EditorSceneManager.SaveScene(s.gameObject.scene);
            r.Log("Fresh r103 save namespace=" + s.data.namespaceId);
            EditorApplication.isPlaying = true;
        }
    }
}

